function registerBoundary(tile,points,normals,weights,sharedIds){const shared=new Set(sharedIds||[]);tile.boundary=[];const row=tile.row,width=1000*2**row[0];for(let i=0;i<points.length;i+=3){const x=points[i],y=points[i+1];if(Math.min(Math.abs(x),Math.abs(width-x),Math.abs(y),Math.abs(width-y))>.02&&!shared.has(i/3))continue;const key=`${row[0]}/${Math.round((row[1]*width+x)*100)}/${Math.round((row[2]*width+y)*100)}/${Math.round(points[i+2]*100)}`,member={tile,index:i/3,normal:[normals[i],normals[i+1],normals[i+2]].map(v=>v*(weights?weights[i/3]:1)),key};let group=boundaryGroups.get(key);if(!group){group=new Set();boundaryGroups.set(key,group);}group.add(member);tile.boundary.push(member);if(group.size>1)refreshBoundary(group);}}
