// 地面の長方形だけで候補を数えず、標高0～4,500 mの箱を視錐台で判定する。
function tileVisible(row){const w=1000*2**row[0],m=matrix(),clips=[];for(const dx of [0,1])for(const dy of [0,1])for(const z of [0,4500]){const x=(row[1]+dx)*w-center[0],y=(row[2]+dy)*w-center[1];clips.push([m[0]*x+m[4]*y+m[8]*z+m[12],m[1]*x+m[5]*y+m[9]*z+m[13],m[2]*x+m[6]*y+m[10]*z+m[14],m[3]*x+m[7]*y+m[11]*z+m[15]]);}for(let axis=0;axis<3;axis++)for(const sign of [-1,1])if(clips.every(p=>sign*p[axis]>p[3]))return false;return true;}

